insert into public.products (id, slug, name, category, brand, description, short_description, price, original_price, stock, images, is_featured, is_best_seller, is_new, sku, active, specifications, curado_o_guia) values
('mate-01', 'mate-imperial-de-calabaza-y-cuero-virola-de-alpaca-cincelada', 'Mate Imperial de calabaza y cuero, virola de alpaca cincelada', 'mates', 'Mates Amancay', 'Mate Imperial de calabaza forrado en cuero, con base de cuatro patas que lo deja firme sobre la mesa y virola de alpaca cincelada con guarda. El modelo clásico para regalar.', 'Calabaza forrada en cuero, base de 4 patas y virola de alpaca cincelada.', 45000, null, 6, array['/productos/mate-imperial-calabaza-cuero-virola-alpaca-cincelada.webp']::text[], false, true, false, 'MATE-01', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Alpaca cincelada","Base":"4 patas"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-02', 'mate-imperial-de-calabaza-y-cuero-virola-de-acero', 'Mate Imperial de calabaza y cuero, virola de acero', 'mates', 'Mates Amancay', 'Mate Imperial de calabaza forrado en cuero, con base de cuatro patas y virola lisa de acero, que no se mancha y se limpia fácil.', 'Calabaza forrada en cuero, base de 4 patas y virola de acero.', 34000, null, 12, array['/productos/mate-imperial-calabaza-cuero-virola-acero.webp']::text[], false, true, false, 'MATE-02', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Acero","Base":"4 patas"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-03', 'mate-camionero-de-calabaza-y-cuero-virola-de-acero', 'Mate Camionero de calabaza y cuero, virola de acero', 'mates', 'Mates Amancay', 'Camionero de calabaza forrado en cuero, de boca ancha y virola de acero. Robusto y cómodo para rondas largas o para llevar.', 'Boca ancha, calabaza forrada en cuero y virola de acero.', 28000, null, 9, array['/productos/mate-camionera-calabaza-cuero-virola-acero.webp']::text[], false, false, false, 'MATE-03', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Acero","Boca":"Ancha"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-04', 'mate-torpedo-de-calabaza-y-cuero-virola-de-aluminio', 'Mate Torpedo de calabaza y cuero, virola de aluminio', 'mates', 'Mates Amancay', 'Torpedo de calabaza forrado en cuero suela con costura a la vista y virola de aluminio. Su forma alargada se agarra bien con una mano.', 'Cuero suela con costura a la vista y virola de aluminio.', 25000, null, 7, array['/productos/mate-torpedo-calabaza-cuero-virola-aluminio.webp']::text[], false, false, false, 'MATE-04', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Aluminio","Forma":"Torpedo"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-05', 'mate-de-calabaza-forrado-en-cuero-con-pie-virola-de-aluminio', 'Mate de calabaza forrado en cuero con pie, virola de aluminio', 'mates', 'Mates Amancay', 'Calabaza forrada en cuero y cosida en tiento, apoyada sobre un pie de metal, con virola de aluminio.', 'Cuero cosido en tiento, pie de metal y virola de aluminio.', 28000, null, 4, array['/productos/mate-calabaza-forrado-cuero-con-pie-virola-aluminio-cocido.webp']::text[], false, false, false, 'MATE-05', true, '{"Cuerpo":"Calabaza forrada en cuero, cosida en tiento","Virola":"Aluminio","Base":"Pie de metal"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-06', 'mate-de-calden-curado-en-horno-con-dije-de-alpaca', 'Mate de caldén curado en horno, con dije de alpaca', 'mates', 'Mates Amancay', 'Mate torneado en caldén, una madera dura y densa del monte pampeano que aguanta bien la humedad y no le cambia el sabor a la yerba. Viene curado en horno y lleva un dije de alpaca.', 'Madera de caldén ya curada en horno, con dije de alpaca.', 19900, null, 8, array['/productos/mate-madera-calden-curado-en-horno-dije-alpaca.webp']::text[], false, false, true, 'MATE-06', true, '{"Cuerpo":"Madera de caldén","Terminación":"Curado en horno","Detalle":"Dije de alpaca"}'::jsonb, null),
('mate-07', 'mate-de-calden-curado-en-horno', 'Mate de caldén curado en horno', 'mates', 'Mates Amancay', 'Mate de caldén torneado y tallado, ya curado en horno: está listo para usar. El caldén es una madera dura que resiste la humedad.', 'Madera de caldén tallada, ya curada en horno.', 14500, null, 15, array['/productos/mate-calden-curado-en-horno.webp']::text[], false, false, false, 'MATE-07', true, '{"Cuerpo":"Madera de caldén","Terminación":"Curado en horno"}'::jsonb, null),
('mate-08', 'mate-ranchero-de-algarrobo-rustico', 'Mate Ranchero de algarrobo rústico', 'mates', 'Mates Amancay', 'Mate ranchero de algarrobo con terminación rústica. El algarrobo tiene un aroma naturalmente dulce que acompaña a la yerba, y la madera toma color con el uso.', 'Algarrobo con terminación rústica y aroma dulce natural.', 19500, null, 10, array['/productos/mate-ranchero-algarrobo-rustico.webp']::text[], false, false, false, 'MATE-08', true, '{"Cuerpo":"Madera de algarrobo","Terminación":"Rústica"}'::jsonb, 'Untá el interior con un poco de manteca o aceite neutro y dejalo actuar una noche. Al día siguiente llenalo con yerba húmeda durante 24 horas y enjuagalo sin detergente.'),
('mate-09', 'porito-de-calabaza-y-cuero-virola-de-aluminio', 'Porito de calabaza y cuero, virola de aluminio', 'mates', 'Mates Amancay', 'Porito de calabaza forrado en cuero marrón con costura en tiento y virola de aluminio. Tamaño chico, ideal para tomar solo.', 'Calabaza forrada en cuero marrón y virola de aluminio.', 25000, null, 5, array['/productos/porito-calabaza-cuero-virola-aluminio.webp']::text[], false, false, false, 'MATE-09', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Aluminio","Tamaño":"Chico"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('mate-10', 'porito-con-base-de-calabaza-y-cuero-virola-de-aluminio', 'Porito con base, de calabaza y cuero, virola de aluminio', 'mates', 'Mates Amancay', 'Porito de calabaza forrado en cuero crudo, con base para apoyarlo y virola de aluminio.', 'Cuero crudo, con base y virola de aluminio.', 25000, null, 3, array['/productos/porito-con-base-calabaza-cuero-virola-aluminio.webp']::text[], false, false, false, 'MATE-10', true, '{"Cuerpo":"Calabaza forrada en cuero","Virola":"Aluminio","Base":"Sí"}'::jsonb, 'Llená el mate con yerba usada y un chorro de agua tibia, dejalo reposar 24 horas y raspá suavemente las paredes con una cuchara. Repetí dos o tres días antes del primer mate.'),
('bomb-01', 'bombilla-pico-de-loro-de-alpaca-cincelada', 'Bombilla pico de loro de alpaca cincelada', 'bombillas', 'Mates Amancay', 'Bombilla de alpaca con caño cincelado, boquilla pico de loro y filtro de cuchara. La alpaca es una aleación que no se oxida y aguanta el uso diario.', 'Alpaca cincelada, pico de loro y filtro de cuchara.', 23500, null, 8, array['/productos/bombilla-pico-de-loro-alpaca-cincelada.webp']::text[], false, true, false, 'BOMB-01', true, '{"Material":"Alpaca","Boquilla":"Pico de loro","Filtro":"Cuchara"}'::jsonb, null),
('bomb-02', 'bombilla-cuchara-pico-de-loro-de-acero-inoxidable', 'Bombilla cuchara pico de loro de acero inoxidable', 'bombillas', 'Mates Amancay', 'Bombilla de acero inoxidable con boquilla pico de loro y filtro de cuchara perforada. Fácil de lavar y no se tapa con yerba de molienda fina.', 'Acero inoxidable, filtro de cuchara perforada.', 9500, null, 20, array['/productos/bombilla-cuchara-acero-inoxidable-pico-de-loro.webp']::text[], false, true, false, 'BOMB-02', true, '{"Material":"Acero inoxidable","Boquilla":"Pico de loro","Filtro":"Cuchara perforada"}'::jsonb, null),
('bomb-03', 'bombilla-chata-de-alpaca', 'Bombilla chata de alpaca', 'bombillas', 'Mates Amancay', 'Bombilla chata de alpaca, de caño plano y filtro de paleta. Un clásico de mostrador.', 'Alpaca, caño plano y filtro de paleta.', 16500, null, 6, array['/productos/bombilla-alpaca-chata.webp']::text[], false, false, false, 'BOMB-03', true, '{"Material":"Alpaca","Formato":"Chata","Filtro":"Paleta"}'::jsonb, null),
('perf-01', 'kevin-absolute', 'Kevin Absolute', 'perfumes', 'Kevin', 'Arranca con pomelo y canela, sigue con un corazón de menta y rosa, y cierra con maderas, ámbar, patchouli y cuero. Tiene presencia sin ser pesado.', 'Pomelo, canela, menta y un fondo de maderas y cuero.', 31500, null, 0, array['/productos/kevin-absolute-perfume.webp']::text[], false, true, false, 'PERF-01', true, '{"Marca":"Kevin","Concentración":"Eau de Toilette","Notas de salida":"Pomelo y canela","Notas de corazón":"Menta y rosa","Notas de fondo":"Maderas, ámbar, patchouli y cuero","Familia olfativa":"Oriental amaderada","Para":"Hombre"}'::jsonb, null),
('perf-02', 'kevin-red', 'Kevin Red', 'perfumes', 'Kevin', 'Salida frutal y especiada de casis, bergamota y pimienta rosa, con un corazón de petit grain y ámbar y un fondo de musgo de roble y almizcle.', 'Casis y pimienta rosa sobre un fondo de musgo y almizcle.', 31500, null, 0, array['/productos/kevin-red-perfume.webp']::text[], false, false, false, 'PERF-02', true, '{"Marca":"Kevin","Concentración":"Eau de Toilette","Notas de salida":"Casis, bergamota y pimienta rosa","Notas de corazón":"Petit grain, ámbar y patchouli","Notas de fondo":"Musgo de roble, hojas de abedul y almizcle","Para":"Hombre"}'::jsonb, null),
('perf-03', 'kevin-dubai', 'Kevin Dubai', 'perfumes', 'Kevin', 'Abre fresco con bergamota, rosa y geranio, gana cuerpo con peonía y cedro, y deja una estela de almizcle, patchouli y musgo de roble.', 'Bergamota y rosa con un fondo de almizcle y patchouli.', 37500, null, 6, array['/productos/kevin-dubai-perfume.webp']::text[], false, false, true, 'PERF-03', true, '{"Marca":"Kevin","Concentración":"Eau de Parfum","Notas de salida":"Bergamota, rosa y geranio","Notas de corazón":"Peonía, cedro y lirio del valle","Notas de fondo":"Almizcle, patchouli y musgo de roble","Familia olfativa":"Amaderada floral","Para":"Hombre","Tamaño":"100 ml"}'::jsonb, null),
('perf-04', 'kevin-eau-de-toilette', 'Kevin Eau de Toilette', 'perfumes', 'Kevin', 'El Kevin de siempre: salvia, nerolí y especias, un corazón de sándalo y patchouli, y un fondo de musk con toques frutales.', 'El clásico: salvia, nerolí, sándalo y patchouli.', 20500, null, 0, '{}', false, false, false, 'PERF-04', true, '{"Marca":"Kevin","Concentración":"Eau de Toilette","Notas de salida":"Salvia, nerolí y especias","Notas de corazón":"Sándalo y patchouli","Notas de fondo":"Musk y notas frutales","Familia olfativa":"Fougère frutal","Para":"Hombre"}'::jsonb, null),
('perf-05', 'kevin-eau-de-cologne', 'Kevin Eau de Cologne', 'perfumes', 'Kevin', 'La colonia de Kevin en frasco de vidrio. Más liviana que el perfume, para usar todos los días o después de la ducha.', 'Colonia liviana para todos los días.', 11900, null, 14, array['/productos/kevin-eau-de-colgne-perfume.webp']::text[], false, false, false, 'PERF-05', true, '{"Marca":"Kevin","Concentración":"Eau de Cologne","Para":"Hombre"}'::jsonb, null),
('perf-06', 'kevin-after-shave', 'Kevin After Shave', 'perfumes', 'Kevin', 'Loción para después del afeitado de la línea Kevin. Se aplica sobre la piel recién afeitada.', 'Loción para después del afeitado.', 12900, null, 8, array['/productos/kevin-after-shave.webp']::text[], false, false, false, 'PERF-06', true, '{"Marca":"Kevin","Concentración":"Loción para después del afeitado","Para":"Hombre"}'::jsonb, null),
('perf-07', 'bross-london-gold', 'Bross London Gold', 'perfumes', 'Bross London', 'Inspirada en las fragancias árabes: pomelo, grosella negra y azafrán al abrir, geranio, rosa y canela en el corazón, y un fondo intenso de cedro, sándalo y ámbar gris.', 'Pomelo y azafrán con fondo de sándalo y ámbar gris.', 30500, null, 9, array['/productos/bross-london-gold-perfume.webp']::text[], false, true, false, 'PERF-07', true, '{"Marca":"Bross London","Concentración":"Eau de Parfum","Notas de salida":"Pomelo, grosella negra y azafrán","Notas de corazón":"Geranio, rosa y canela","Notas de fondo":"Cedro, sándalo, ámbar gris y patchouli","Familia olfativa":"Oriental amaderada","Para":"Hombre","Tamaño":"100 ml"}'::jsonb, null),
('perf-08', 'bross-london-hawaii', 'Bross London Hawaii', 'perfumes', 'Bross London', 'Una fragancia relajada: cítricos frescos y pera que se mezclan con jazmín y muguet, sobre un fondo cálido de ámbar.', 'Cítricos y pera con jazmín y un fondo de ámbar.', 30500, null, 7, array['/productos/bross-london-hawaii-perfume.webp']::text[], false, false, false, 'PERF-08', true, '{"Marca":"Bross London","Concentración":"Eau de Toilette","Notas de salida":"Cítricos frescos y pera","Notas de corazón":"Jazmín y muguet","Notas de fondo":"Ámbar","Familia olfativa":"Amaderada ambarada","Para":"Hombre","Tamaño":"100 ml"}'::jsonb, null),
('perf-09', 'bross-london-warrior', 'Bross London Warrior', 'perfumes', 'Bross London', 'Salida especiada que se asienta en un corazón de maderas y termina en un fondo cálido de ámbar y musk.', 'Especias y maderas con fondo de ámbar y musk.', 30500, null, 6, array['/productos/bross-london-warrior-perfume.webp']::text[], false, false, false, 'PERF-09', true, '{"Marca":"Bross London","Concentración":"Eau de Toilette","Notas de salida":"Especias intensas","Notas de corazón":"Maderas","Notas de fondo":"Ámbar y musk","Familia olfativa":"Especiada amaderada","Para":"Hombre","Tamaño":"100 ml"}'::jsonb, null),
('perf-10', 'carocuore', 'CaroCuore', 'perfumes', 'CaroCuore', 'El clásico de la caja roja: fresias y peonías al abrir, un corazón de rosas y un fondo amaderado de sándalo y cedro.', 'Fresias, peonías y rosas sobre sándalo y cedro.', 35500, null, 8, array['/productos/carocuore-perfume.webp']::text[], false, true, false, 'PERF-10', true, '{"Marca":"CaroCuore","Concentración":"Eau de Toilette","Notas de salida":"Fresias y peonías","Notas de corazón":"Rosas","Notas de fondo":"Sándalo y cedro","Familia olfativa":"Floral","Para":"Mujer"}'::jsonb, null),
('perf-11', 'carocuore-amore', 'CaroCuore Amore', 'perfumes', 'CaroCuore', 'Fresca y juvenil: lychee, bergamota y durazno que se abren a un corazón floral y un fondo de sándalo, almizcle y cedro.', 'Lychee y durazno con un fondo de sándalo.', 35500, null, 5, array['/productos/carocuore-amore-perfume.webp']::text[], false, false, false, 'PERF-11', true, '{"Marca":"CaroCuore","Concentración":"Eau de Toilette","Notas de salida":"Lychee, bergamota y durazno","Notas de corazón":"Notas florales","Notas de fondo":"Sándalo, almizcle y cedro","Familia olfativa":"Floral frutal","Para":"Mujer"}'::jsonb, null),
('perf-12', 'carocuore-cuore', 'CaroCuore Cuore', 'perfumes', 'CaroCuore', 'Salida fresca y luminosa, corazón de flores blancas y un fondo amaderado que la vuelve suave y envolvente.', 'Flores blancas sobre un fondo amaderado.', 35500, null, 6, array['/productos/carocuore-cuore-perfume.webp']::text[], false, false, false, 'PERF-12', true, '{"Marca":"CaroCuore","Concentración":"Eau de Toilette","Notas de salida":"Notas frescas","Notas de corazón":"Flores blancas","Notas de fondo":"Acordes amaderados","Familia olfativa":"Floral suave","Para":"Mujer"}'::jsonb, null),
