('perf-14', 'acqua-di-colbert', 'Acqua di Colbert', 'perfumes', 'Colbert', 'Fresca y cítrica: cítricos frutados al abrir, un corazón de maderas y especias, y un fondo de musgo, lavanda y patchouli.', 'Cítricos frutados con un fondo de lavanda y musgo.', 16600, null, 0, array['/productos/acqua-di-colbert-perfume.webp']::text[], false, false, false, 'PERF-14', true, '{"Marca":"Colbert","Concentración":"Eau de Toilette","Notas de salida":"Cítricos frutados","Notas de corazón":"Maderas y especias","Notas de fondo":"Musgo, lavanda y patchouli","Familia olfativa":"Cítrica","Para":"Hombre"}'::jsonb, null),
