('perf-16', 'valeria-by-valeria-mazza', 'Valeria by Valeria Mazza', 'perfumes', 'Valeria Mazza', 'Fresca y floral: fresia, bergamota y nectarina, un corazón de jazmín, magnolia y rosa, y un fondo de almizcle, sándalo y ámbar.', 'Fresia y nectarina con jazmín y un fondo de sándalo.', 33000, null, 4, array['/productos/valeria-by-valeria-mazza-perfume.webp']::text[], false, false, false, 'PERF-16', true, '{"Marca":"Valeria Mazza","Concentración":"Eau de Parfum","Notas de salida":"Fresia, bergamota y nectarina","Notas de corazón":"Jazmín, magnolia, casis y rosa","Notas de fondo":"Almizcle, sándalo, cedro y ámbar","Familia olfativa":"Floral","Para":"Mujer","Tamaño":"100 ml"}'::jsonb, null),
